export const PAPERS: PaperInput[] = [
  {"id":"2609.35259","title":"On-Policy or Off-Policy Learning? A Systematic Study of Distillation Dynamics","up":180,"href":"https://arxiv.org/abs/2609.35259","abstract":"On-policy learning has been argued to reduce catastrophic forgetting, produce sparser parameter updates, and improve generalisation. However, existing comparisons between supervised fine-tuning and reinforcement learning vary many factors simultaneously, making the contribution of rollout policy difficult to isolate. We study the effect of rollout policy in a controlled strong-to-weak distillation setting, by independently varying rollout policy, token-level KL direction, and learning rate across the Llama3 and Qwen2.5 model families and reasoning tasks spanning scientific, medical, and arithm","pdfUrl":"https://arxiv.org/pdf/2609.35259","primaryCategory":"cs.LG","crossrefDoi":"https://doi.org/10.1109/tnnls.2024.3373749/mm1"},
  {"id":"2609.38879","title":"Does Learning Protein Folding Generalize to Broader Reasoning?","up":105,"href":"https://arxiv.org/abs/2609.38879","abstract":"Large language models rely heavily on human text, which often conveys surface answers rather than the spatial and structural logic behind them. Protein folding is a natural testbed, because one solved structure yields thousands of exactly checkable spatial and topological statements. We ask: can learning to fold proteins teach general models reusable reasoning capabilities? To answer this, we build FoldingCorpus, a protein-derived question-answer dataset, and Fold2Reason, a recipe that post-trains on it through two complementary signals: discrete structural answers predicted via the model's na","pdfUrl":"https://arxiv.org/pdf/2609.38879","primaryCategory":"cs.LG"},
  {"id":"2609.36585","title":"Transformers Stop Thinking Too Early, and a Tiny LoRA Fixes It","up":73,"href":"https://arxiv.org/abs/2609.36585","abstract":"Pretrained transformers use little of their depth to follow references in context. Thirteen base models reliably follow only 1.4-3.6 lines, and extra pretrained loops add little. A task-trained rank-8 LoRA at one early layer extends this computation with all model weights frozen. Qwen3-8B improves from 15.5% to 99% exact accuracy on 24-line chains; a longer-trained LoRA reaches 50 lines. Ouro-1.4B reaches 60 lines after four loops and at least 160 after eight. The LoRA starts a relay: program lines pass on their chain identity through a short range of middle layers. Frozen heads read progressi","pdfUrl":"https://arxiv.org/pdf/2609.36585","primaryCategory":"cs.AI"},
  {"id":"2609.32993","title":"X-Tree: Tokenizing Reusable Experience for Efficient Agent Generalization","up":67,"href":"https://arxiv.org/abs/2609.32993","abstract":"Multi-step agents are trained on flat action streams: SFT and RLVR weight every token uniformly and ignore the sub-procedures that recur across tasks, the hierarchy that lets humans plan top-down from reusable routines. This structure sits unused, and flat training uses each scarce trajectory less fully than its content allows. Recent agents do use that structure, but only as LLM-written skills in context, never in the weights, so their gains do not generalize beyond retrieval. We instead recover this hierarchy from the data itself and train on it, with no LLM calls. Following text tokenizers,","pdfUrl":"https://arxiv.org/pdf/2609.32993","primaryCategory":"cs.AI"},
  {"id":"2609.38078","title":"MotorMind: Scaffolding General Vision Language Models for Zero-Shot Robot Manipulation","up":65,"href":"https://arxiv.org/abs/2609.38078","abstract":"Vision-language-action (VLA) models have advanced robotic manipulation, but their zero-shot generalization in new tasks and environments remains limited, and their reliance on specialized training keeps them from benefiting directly from rapidly advancing general-purpose vision-language models (VLMs). In parallel, recent agentic robotic systems leverage VLMs for high-level reasoning or coding agents for robot control, but often depend on extensive external models and tools, introducing additional complexity and cost. This motivates us to ask: Can a general-purpose VLM itself operate a robot mo","pdfUrl":"https://arxiv.org/pdf/2609.38078","primaryCategory":"cs.RO"},
  {"id":"2610.00812","title":"Video Generation Models: A Survey of Post-Training and Alignment","up":56,"href":"https://arxiv.org/abs/2610.00812","abstract":"Video generation has rapidly progressed from short, low-quality clips to high-resolution, long-duration sequences with complex spatiotemporal dynamics. Despite strong generative priors learned through large-scale pretraining, pretrained video models often fail to reliably follow human intent, maintain temporal coherence, or satisfy physical and safety constraints. Compared with image and text generation, alignment in video generation presents unique challenges, including error accumulation over time, motion-appearance coupling, multi-objective trade-offs, and limited supervision for temporal p","pdfUrl":"https://arxiv.org/pdf/2610.00812","primaryCategory":"cs.CV"},
  {"id":"2609.38839","title":"FrameMorrow: Future-guided Frame Selection with Prospective Tokens for Long-Horizon Video Generation","up":51,"href":"https://arxiv.org/abs/2609.38839","abstract":"Long-horizon video generation requires models to effectively leverage an increasingly long generation history. As the generated history grows, retaining all previous content becomes increasingly expensive and redundant, making effective historical selection essential. Existing approaches often determine historical relevance based on the current content. However, information relevant to the present is not necessarily useful for future generation, while seemingly less relevant history may become important later. Our key insight is that historical information should be selected according to its r","pdfUrl":"https://arxiv.org/pdf/2609.38839","primaryCategory":"cs.CV"},
  {"id":"2609.36388","title":"Persona Dosing: Calibrated Activation Steering for Graded Trait Control","up":50,"href":"https://arxiv.org/abs/2609.36388","abstract":"An activation-steering coefficient sets intervention strength, but requesting a particular degree of persona expression requires a behavioral scale. We study persona dosing: controlling a language model through a trait description and a requested mean intensity. PersonaDose specializes a shared, description-conditioned FLAS controller on persona responses, then calibrates its flow time against measured trait expression. Training responses are not paired with requested target intensities. Across Llama-3.1-8B, Qwen3-8B, and Gemma-3-4B, PersonaDose raises core-trait expression at the Persona Vect","pdfUrl":"https://arxiv.org/pdf/2609.36388","primaryCategory":"cs.AI"},
  {"id":"2610.02826","title":"Scaling Trajectories for Complex Tasks through Recursive Self-Rewrite","up":39,"href":"https://arxiv.org/abs/2610.02826","abstract":"Successful trajectories on difficult tasks provide valuable supervision for model improvement, but specialized harnesses introduce interventions that may be unavailable during deployment. We propose Recursive Self-Rewrite (RSR), a framework that uses one base model, Qwen-3.8-27B, to discover successful solutions under diverse harnesses and reconstruct them as training trajectories under a general harness. A planner extracts procedures into runbooks, a critic screens for verifier and solution leakage and guides recursive revision, and an executor follows qualified runbooks in fresh sandboxes. A","pdfUrl":"https://arxiv.org/pdf/2610.02826","primaryCategory":"cs.AI"},
  {"id":"2610.01092","title":"Ego2Act: Evaluating Goal-Directed Manipulation in Egocentric Video Generation","up":26,"href":"https://arxiv.org/abs/2610.01092","abstract":"Video generation models are increasingly being explored as world simulators for embodied planning and learning. To do so effectively, these models must not only generate visually appealing frames, but also predict how environments dynamically evolve when executing goal-directed actions. While evaluating these capabilities is crucial, existing benchmarks focus mainly on single short actions or step-by-step instructions. This leaves multi-step physical reasoning underexplored, especially in egocentric video generation that requires planning to simulate proper execution to accomplish high-level g","pdfUrl":"https://arxiv.org/pdf/2610.01092","primaryCategory":"cs.CV"},
  {"id":"2610.02508","title":"World Action Modeling with Progressive Visual Planning","up":26,"href":"https://arxiv.org/abs/2610.02508","abstract":"World action models (WAMs) have emerged as a promising paradigm for robotic control by jointly predicting future visual dynamics and actions from an initial observation and instruction. However, existing WAMs struggle with long-horizon prediction, as generating dense video rollouts is highly inefficient. Some recent WAMs address this by predicting a single future frame without generating the full video, but this approach neglects how to progress toward the goal. We present ProWAM, a progressive world action model that jointly predicts actions and an ordered sequence of sparse visual sub-goals,","pdfUrl":"https://arxiv.org/pdf/2610.02508","primaryCategory":"cs.AI"},
  {"id":"2610.03391","title":"Native Action-Prior Learning from Videos for World Action Models","up":21,"href":"https://arxiv.org/abs/2610.03391","abstract":"World action models integrate future visual dynamics with robot action prediction, but their scalability remains limited by the need for action-annotated robot trajectories. Observation-only videos contain rich evidence about interaction dynamics, but existing approaches typically use them either to pretrain visual representations that must later be adapted for control, or to infer latent actions that are subsequently grounded to robot commands. We present NAVA-WAM, which introduces native action-prior learning by directly pretraining the action policy from observation-only videos, avoiding in","pdfUrl":"https://arxiv.org/pdf/2610.03391","primaryCategory":"cs.CV"},
  {"id":"2609.34715","title":"PDE-JEPA: Predictive Representation Learning of Latent Dynamics Modeling for Parametric PDEs","up":19,"href":"https://arxiv.org/abs/2609.34715","abstract":"Physical trajectories contain more than snapshots of a system: they also reveal how its states evolve under governing conditions. However, representation learning for parametric partial differential equations (PDEs) has largely relied on reconstruction-based objectives that emphasize recovering observed physical fields. In this paper, we investigate predictive representation pretraining as an alternative to reconstruction-based learning. We find that predictive representations preserve rich physical information, yet this advantage alone does not ensure accurate field evolution. Based on these ","pdfUrl":"https://arxiv.org/pdf/2609.34715","primaryCategory":"cs.AI"},
  {"id":"2610.03665","title":"Pivot-SD: Efficient Self-Distillation for Masked Diffusion Language Models","up":19,"href":"https://arxiv.org/abs/2610.03665","abstract":"Masked diffusion language models (dLMs) offer a promising parallel alternative to autoregressive models for complex reasoning. However, they face a distinct credit-assignment challenge, since a few commitments during denoising sharply reduce the uncertainty over the remaining masked positions and shape much of the response. Most post-training recipes for dLMs do not use this signal to decide which tokens to train on: they typically train on the final text or assign rewards to whole denoising steps, rather than selecting the individual commitments that shape the response. We introduce Pivot-SD,","pdfUrl":"https://arxiv.org/pdf/2610.03665","primaryCategory":"cs.LG"},
  {"id":"2610.02304","title":"SimuVerity: Benchmarking Agents for Engineering-Grade Simulink Model Generation","up":18,"href":"https://arxiv.org/abs/2610.02304","abstract":"Existing Simulink benchmarks mainly evaluate whether generated models compile, execute, or resemble a reference model. These criteria do not establish whether a model satisfies its engineering requirements. We introduce SimuVerity, a benchmark of 101 text-to-executable Simulink model-generation tasks across ten engineering domains. For each task, executable-system profiles ground the engineering specification and four families of native simulation scenarios. A hierarchical evaluator first checks artifact delivery, native executability, and engineering qualification, then scores qualified model","pdfUrl":"https://arxiv.org/pdf/2610.02304","primaryCategory":"cs.SE"},
  {"id":"2610.03574","title":"HyperBrowseComp: A Multilingual and Multimodal Stress Test for Web-Browsing Agents","up":17,"href":"https://arxiv.org/abs/2610.03574","abstract":"We introduce HyperBrowseComp, a multilingual and multimodal browsing benchmark comprising 423 manually authored and human-validated questions across 13 languages, written by native or highly proficient speakers. Questions are designed to be extremely challenging. Each question targets a concise, publicly verifiable answer whose discovery requires locating obscure evidence, following multi-step clue chains, or inspecting heterogeneous sources such as videos, scanned documents, images, or maps. Easier questions are filtered out by evaluating them with models without internet access to reduce the","pdfUrl":"https://arxiv.org/pdf/2610.03574","primaryCategory":"cs.AI"},
  {"id":"2610.03632","title":"World Embedding Benchmark","up":16,"href":"https://arxiv.org/abs/2610.03632","abstract":"Physical fidelity has received increasing attention in world models and video generation, yet how video representations encode physical information remains less understood. We introduce the World Embedding Benchmark, comprising 8,000 controlled simulation cases from 80 families spanning fluid mechanics, solid mechanics, dynamics, and optics & electromagnetism. Each case pairs a rendered video with simulation-derived physical annotations, supporting three complementary tasks: text-video retrieval, physical-property regression, and multiple-choice video-description pair classification. We use th","pdfUrl":"https://arxiv.org/pdf/2610.03632","primaryCategory":"cs.CV"},
  {"id":"2610.03195","title":"Source Preference in the Wild: How LLM Agents Favor Items by Source, and How to Reduce It","up":15,"href":"https://arxiv.org/abs/2610.03195","abstract":"As LLM agents decide on users' behalf which product to buy, which hotel to book, or which paper to cite, a preference for items from certain sources (the sites or services they come from) shapes what users receive and which sources are selected. We study source preference in end-to-end search with 12 agent models across three domains. Comparing items from different sources that satisfy the same requirements at the same position, we find that each model prefers some sources and avoids others in every domain, largely agreeing on which. This preference can outweigh how well items satisfy the requ","pdfUrl":"https://arxiv.org/pdf/2610.03195","primaryCategory":"cs.CL"},
  {"id":"2609.32810","title":"OpenTumorBoard: A Real-World Benchmark of Multidisciplinary Tumor Board Discussion Trajectories","up":14,"href":"https://arxiv.org/abs/2609.32810","abstract":"Multidisciplinary tumor boards integrate multimodal clinical observations and longitudinal patient histories through specialist discussions, yet benchmarks rarely capture these real-world trajectories. We introduce OpenTumorBoard, a benchmark with 611 patient cases and 19,157 discussion turns across ten specialist roles, transcribed from 12,534 minutes of publicly available tumor board recordings on YouTube. The benchmark evaluates two settings: SPECIALIST TURN, in which an LLM responds to a clinically significant question posed during a real discussion, and BOARD SIMULATION, in which it gener","pdfUrl":"https://arxiv.org/pdf/2609.32810","primaryCategory":"cs.CL"},
  {"id":"2609.39071","title":"LexReward: A Taxonomy-Driven Reward Framework for Legal Language Models","up":14,"href":"https://arxiv.org/abs/2609.39071","abstract":"Legal language models require reward signals that capture not only answer correctness but also the multidimensional quality of legal responses. Existing reward methods, however, often rely on coarse-grained holistic judgments, providing limited domain specificity and interpretability. We introduce LexReward, a taxonomy-driven framework for legal reward modeling. LexReward characterizes legal response quality along three complementary dimensions: Style, covering lexical and syntactic quality; Element, assessing legal subjects, facts, statutes, and decisions; and Chain, evaluating the order, com","pdfUrl":"https://arxiv.org/pdf/2609.39071","primaryCategory":"cs.CL"},
  {"id":"2609.34210","title":"RLE-Bench: A Qualifying Exam for Coding Agents as Robot Learning Engineers","up":12,"href":"https://arxiv.org/abs/2609.34210","abstract":"Coding agents are beginning to move beyond purely digital tasks to tackle physical-world challenges, particularly in robotics. Existing robotics benchmarks, however, primarily focus on the performance of individual artifacts, such as policies or controllers, offering limited coverage of coding agents' broader engineering capabilities. Real-world robotics extends beyond control: agents must build, integrate, diagnose, and improve heterogeneous artifacts under resource constraints and reason from multimodal feedback. To evaluate these broader capabilities, we introduce RLE-Bench, a benchmark of ","pdfUrl":"https://arxiv.org/pdf/2609.34210","primaryCategory":"cs.RO"},
  {"id":"2610.00531","title":"Science or Slop?: Benchmarking and Mitigating Scientific Slop in AI-Generated Papers","up":11,"href":"https://arxiv.org/abs/2610.00531","abstract":"AI-generated content, often called AI slop, is increasingly common everywhere, particularly in academia. Slop in AI-generated scientific papers, however, has more complex patterns that cannot be easily detected by existing token-based AI detectors. Each part of such a paper looks plausible while the scientific reasoning that connects the parts breaks down, which can mislead how readers assess the work. We benchmark these failures as scientific slop through six measures across Structure, Argument, and Artifacts. We construct SciSlopBench with 390 AI-generated papers, mostly in computer science ","pdfUrl":"https://arxiv.org/pdf/2610.00531","primaryCategory":"cs.AI"},
  {"id":"2610.00686","title":"SemanTok: Predictable Semantic Tokens for Efficient Autoregressive Video Generation","up":11,"href":"https://arxiv.org/abs/2610.00686","abstract":"Recent video-based world models pair the scalability of autoregressive (AR) prediction with the visual quality of diffusion models. The choice of scene tokenizer is paramount for the optimal performance of each of these, both in terms of fidelity and semantics. Flexible-length, coarse-to-fine tokenizers yield exactly that: the first coarse tokens carry the clip's global semantics while later tokens further specify details. Existing flexible tokenizers only apply a representation-alignment (REPA) loss on early decoder hidden states, a target the decoder can partly meet from its noised input ins","pdfUrl":"https://arxiv.org/pdf/2610.00686","primaryCategory":"cs.CV"},
  {"id":"2610.02202","title":"ScholarCatalyst: A Benchmark for Retrieving Papers That Inspire New Research","up":11,"href":"https://arxiv.org/abs/2610.02202","abstract":"What makes great scientists great? Even as AI systems start to make progress on open problems, scientists remain far ahead of them at sensing which prior idea, buried in an ever-growing archive of research, a new problem needs. To study this skill, we draw on researchers who know firsthand which earlier work advanced their completed projects, with papers serving as pointers to the ideas within. Using our automated pipeline that makes author annotation scalable, we build ScholarCatalyst by having 184 lead authors of 207 recent computer science papers label which candidates did or could have adv","pdfUrl":"https://arxiv.org/pdf/2610.02202","primaryCategory":"cs.AI"},
];

